use v5.42;
use strict;
use warnings;
use JSON::PP ();
use File::Basename 'dirname';
use Time::HiRes qw(clock_gettime CLOCK_MONOTONIC);
use Digest::SHA 'sha256_hex';
use Cwd 'abs_path';
use File::Temp 'tempfile';
use IPC::Open3;
@ARGV == 3 or die "usage: capture-api.pl PERL WORKER METADATA\n";
my ($binary, $worker, $metadata_path) = @ARGV;
sub contents ($path) {
	open my $in, '<', $path or die $!;
	my $text = do {local $/; <$in>};
	close $in or die $!;
	return $text;
}
sub capture (@command) {
	my ($errors) = tempfile(UNLINK => 1);
	my ($input, $in);
	my $pid = open3($input, $in, '>&' . fileno($errors), @command);
	close $input or die $!;
	my $text = do {local $/; <$in>};
	close $in or die $!;
	waitpid($pid, 0) == $pid or die $!;
	my $status = $?;
	seek $errors, 0, 0 or die $!;
	my $diagnostics = do {local $/; <$errors>};
	!$status && !length($diagnostics) or die "command failed ($status): @command\n$diagnostics";
	return $text;
}
my $revision = capture('git', 'rev-parse', 'HEAD'); chomp $revision;
for my $key (qw(PERL5OPT PERL5LIB PERLLIB PERL_UNICODE PERL_HASH_SEED PERL_PERTURB_KEYS PERLIO)) { delete $ENV{$key} }
local $ENV{LC_ALL} = 'C';
local $ENV{LANG} = 'C';
capture('git', 'status', '--porcelain') eq '' or die "dirty benchmark source\n";
my %hashes = map {$_ => sha256_hex(contents($_))} ($binary, $worker, 'perl/lib/Wump.pm', 'perl/core/wump_core.c', 'perl/core/wump_memory.c', 'perl/core/wump_publish.c', 'perl/apply.pl');
my $cpu = contents('/proc/cpuinfo'); $cpu =~ /^model name\s*:\s*(.+)$/m or die;
my $cpu_model = $1;
my $kernel = capture('uname', '-srmo'); chomp $kernel;
my $config = capture($binary, '-I' . dirname($binary) . '/lib', '-MConfig', '-MJSON::PP', '-e',
	q{print JSON::PP::encode_json({map {$_ => $Config::Config{$_} // ''} qw(version archname cc gccversion ccflags ldflags lddlflags optimize usemultiplicity useithreads use64bitall)})});
my $entry_check = capture($binary, '-I'.dirname($binary).'/lib', '-Iperl/lib', '-MB', '-e', q{
	require Wump;
	no strict 'refs';
	for my $name (qw(send recv close)) {
		my $native=B::svref_2object(\&{"Wump::_channel_$name"})->XSUB;
		my $compat=B::svref_2object(\&{"Wump::_$name"})->XSUB;
		die "channel entries must be distinct\n" unless $native && $compat && $native!=$compat;
	}
	print "distinct entries verified\n";
});
$entry_check eq "distinct entries verified\n" or die "invalid entry check\n";
my $sequence = 0;
for my $run (1..7) {
	for my $op (qw(buffered rendezvous)) {
		my $n = $op eq 'buffered' ? 200000 : 50000;
		my @modes = qw(wrapper xs native);
		for my $slots (1, 4) {
			local $ENV{WUMPPROCS} = $slots;
			for my $offset (0..$#modes) {
				my $mode = $modes[($offset + $run - 1) % @modes];
				my $started = clock_gettime(CLOCK_MONOTONIC);
				my $text = capture('taskset', '-c', '0,2,4,6', 'timeout', '90s', $binary,
					'-I' . dirname($binary) . '/lib', '-Iperl/lib', $worker, $op, $mode, $n);
				my $elapsed = clock_gettime(CLOCK_MONOTONIC) - $started;
				my $value = JSON::PP::decode_json($text);
				$value->{completed} == $n && $value->{iterations} == $n
					&& $value->{checksum} == $n*($n+1)/2 + ($op eq 'rendezvous' ? $n : 0)
					&& $value->{operation} eq $op && $value->{mode} eq $mode
					&& $value->{slots} == $slots && $value->{wall_seconds} > 0
					&& $value->{wall_seconds} <= $elapsed or die "bad result\n";
				print JSON::PP->new->canonical->encode({%$value, run => $run,
					sequence => ++$sequence, process_seconds => $elapsed}), "\n";
			}
		}
	}
}
for my $path (keys %hashes) { sha256_hex(contents($path)) eq $hashes{$path} or die "changed file: $path\n" }
capture('git', 'status', '--porcelain') eq '' or die "source changed during measurement\n";
open my $out, '>', "$metadata_path.tmp" or die $!;
print {$out} JSON::PP->new->canonical->pretty->encode({
	source_revision => $revision, source_dirty => JSON::PP::false, binary => abs_path($binary),
	sha256 => \%hashes, config => JSON::PP::decode_json($config),
	cpu_model => $cpu_model, kernel => $kernel, affinity => '0,2,4,6',
	runs => 7, iterations => {buffered => 200000, rendezvous => 50000}, samples => $sequence,
	distinct_native_and_compatibility_entries => JSON::PP::true,
	runner_source => contents(__FILE__),
}) or die $!;
close $out or die $!;
rename "$metadata_path.tmp", $metadata_path or die $!;
